  const htmlText = document.documentElement.outerHTML;
  const urls = (htmlText.match(/https?:\/\/[^'"<>\s)\\]+/g) || []);
  const uniq = Array.from(new Set(urls));
  document.title = "URLS " + uniq.length + " :: " + uniq.slice(0,15).join(" || ");
})();
EOF
