(function(){
  const out = [];
  const ok=(n,c)=>{out.push((c?'PASS':'FAIL')+' '+n); if(!c)throw new Error(n)};
  document.getElementById('btnOpen').click();
  const ul = document.querySelectorAll('.disc-list')[0];
  const items = Array.from(ul.children);
  const a = items[0], d = items[3];
  const ta = a.querySelector('.disc-text').textContent;
  const td = d.querySelector('.disc-text').textContent;
  const rA = a.getBoundingClientRect(), rD = d.getBoundingClientRect();
  const cx = rA.left + rA.width/2;
  const opts = {bubbles:true, cancelable:true, pointerId:1, pointerType:'mouse', clientX:cx, isPrimary:true};
  function fire(t, el, y){ el.dispatchEvent(new PointerEvent(t, Object.assign({}, opts, {clientY:y, buttons:t==='pointerup'?0:1}))); }
  fire('pointerdown', a, rA.top+5);
  fire('pointermove', a, rA.top+2);   // not enough yet -> no move
  let movedBefore = a.classList.contains('is-dragging');
  fire('pointermove', a, rA.top + rD.height + 5); // below -> moves toward bottom
  let movedAfter  = a.classList.contains('is-dragging');
  const orderBeforeUp = Array.from(ul.children).map(li=>li.querySelector('.disc-text').textContent).join(',');
  fire('pointerup', a, rA.top + rD.height + 5);
  const orderFinal = Array.from(ul.children).map(li=>li.querySelector('.disc-text').textContent).join(',');
  const ranks = Array.from(ul.children).map(li=>li.querySelector('.disc-rank').textContent).join(',');
  document.title = 'DRAG movedBefore='+movedBefore+' movedAfter='+movedAfter+' | order: '+orderFinal+' | ranks: '+ranks+' | '+out.join(';');
})();
EOF
