cd /tmp && cat > drag2.js <<'EOF'
(function(){
  const log = [];
  document.getElementById('btnOpen').click();
  const ul = document.querySelectorAll('.disc-list')[0];
  const items = Array.from(ul.children);
  const a = items[0];
  const rA = a.getBoundingClientRect();
  const rD = items[3].getBoundingClientRect();
  const cx = rA.left + rA.width/2;
  const opts = {bubbles:true, cancelable:true, pointerId:1, pointerType:'mouse', clientX:cx, isPrimary:true};
  const fire=(t,el,y)=>{
    let err=null;
    try { el.dispatchEvent(new PointerEvent(t, Object.assign({},opts,{clientY:y,buttons:t==='pointerup'?0:1}))); }
    catch(e){ err=' '+t+': '+e.message; log.push(err);}
    log.push(t+' order='+Array.from(ul.children).map(li=>li.querySelector('.disc-rank'))[0]);
  };
  fire('pointerdown', a, rA.top+5);
  fire('pointermove', a, rA.top+3);
  fire('pointermove', a, rD.top + rD.height/2 + 4);
  log.push('final order='+Array.from(ul.children).map(li=>li.querySelector('.disc-text').textContent).join(','));
  log.push('is-dragging='+a.classList.contains('is-dragging'));
  document.title = 'D2 :: '+log.join(' | ');
})();
EOF
